/**
 * Build-time constants injected by `vite.config.ts` via `define`.
 *
 * `__DEV_SERVER__` is the gate on demo authentication. It is `true` only when Vite
 * is running `vite dev` (`command === 'serve'`) and `false` for every production
 * build, in both the client and the SSR/worker bundle.
 *
 * It replaces `import.meta.env.DEV` for that purpose because `define` is applied to
 * every environment Vite builds, whereas `import.meta.env.DEV` is left as a runtime
 * lookup in the SSR bundle this project builds with `@cloudflare/vite-plugin`. A gate
 * that folds in only one of the two outputs is not a gate.
 *
 * It is deliberately not derived from any environment variable. `PUBLIC_DEMO_MODE`
 * is read from the build's environment, so a CI variable, a copied `.env`, or a
 * platform dashboard setting could set it — which is why a flag could never carry
 * this guarantee on its own.
 */
declare const __DEV_SERVER__: boolean;

/**
 * Whether Vite built the dedicated public demo (`--mode demo`, `build:demo`).
 *
 * The second half of the demo gate, and the only way a PRODUCTION build may use
 * seeded data. It is a build-mode signal like `__DEV_SERVER__`, not an
 * environment variable, so it cannot be turned on by a CI variable, a copied
 * `.env` or a platform setting. An ordinary `vite build` substitutes a literal
 * `false`, which is what keeps the pilot/live bundle's demo paths dead code.
 */
declare const __DEMO_BUILD__: boolean;

/**
 * Worker bindings `src/routes/api.send-invite.ts` reads at runtime.
 *
 * Declared here rather than in `wrangler.jsonc` on purpose. Those three are set
 * with `wrangler secret put`, and a secret must not sit in a config file — the
 * commented block in `wrangler.jsonc` says the same about `GEMINI_API_KEY`.
 * `worker-configuration.d.ts` is generated by `wrangler types` and gitignored, so
 * it is not a place to declare anything either; augmenting the global `Env`
 * here keeps the expectation visible in source and survives a fresh checkout.
 *
 * `SUPABASE_SERVICE_ROLE_KEY` is read by `src/routes/api.accept-invite.ts`, which
 * creates a confirmed auth user for the address on a valid invitation. It is the
 * only privileged key in the project and it exists on the Worker only — see that
 * route for why no other API can do this job.
 *
 * `RESEND_FROM` is a verified sender, not a secret, but it is declared with the
 * others so the route reports all three missing together rather than one at a
 * time.
 *
 * All optional, because each route must still typecheck and boot when its bindings
 * are absent — it reports the missing configuration instead of throwing.
 */
interface Env {
  RESEND_API_KEY?: string;
  RESEND_FROM?: string;
  PUBLIC_APP_URL?: string;
  SUPABASE_SERVICE_ROLE_KEY?: string;
}

/*
 * The same three on `Cloudflare.Env`, because `import { env } from
 * 'cloudflare:workers'` is typed against the namespaced interface while
 * `worker-configuration.d.ts` declares the global one. Declaring only the global
 * interface type-checks nothing and fails with
 * `Property 'RESEND_API_KEY' does not exist on type 'Env'`.
 */
declare namespace Cloudflare {
  interface Env {
    RESEND_API_KEY?: string;
    RESEND_FROM?: string;
    PUBLIC_APP_URL?: string;
    SUPABASE_SERVICE_ROLE_KEY?: string;
  }
}